UPDATE t_p88532089_it_company_website_r.legal_cases
SET description = description || '

ПОГАШЕНИЕ ДОЛГА (ключевой факт):
Долг 86 267,82 оплачен 26.08.2026 НАЛИЧНЫМИ в кассу истца через ККТ ООО «Декоратор», отдельным чеком по КАЖДОЙ из 8 партий.
- чеки ККТ самого истца = первичные документы (54-ФЗ), данные ушли в ОФД и ФНС, оспорить невозможно;
- адресная оплата по каждой партии = ст. 319.1 ГК РФ, истец не вправе отнести деньги на другие обязательства;
- расчёт истца составлен на 17.08.2026, оплата 26.08.2026 — на дату рассмотрения долга нет, просрочка прекращена 26.08.2026;
- фактические дни до оплаты: УПД 12697 — 132, 14271/14273/14277 — 124, 15066 — 119, 15441 — 118, 17160 — 106, 17562 — 105.
ПРОВЕРИТЬ: дату поступления иска в суд. Если позже 26.08.2026 — истец знал о погашении и всё равно требовал долг.',
    next_step = 'Подать возражения + контррасчёт, приложив кассовые чеки от 26.08.2026 по каждой из 8 партий. Позиция: (1) долг погашен 26.08.2026 через кассу истца — в этой части отказать; (2) исключить 94 643,66 руб., начисленные на 29 полностью оплаченных партий; (3) снизить остаток по ст. 333 ГК РФ до 3 282,55 руб. по ставке ЦБ 18%; (4) отказать в процентах на будущее. Уточнить дату поступления иска в суд — если после 26.08.2026, заявить о взыскании судебных расходов с истца.'
WHERE id = 2;

UPDATE t_p88532089_it_company_website_r.legal_documents
SET content = replace(content, 'ПРОСИМ: исключить 94 643,66 руб.', 'ПОГАШЕНИЕ: долг 86 267,82 оплачен 26.08.2026 наличными в кассу истца через ККТ, отдельным чеком по каждой из 8 партий. Расчёт истца — на 17.08.2026, оплата на 9 дней позже. Просрочка прекращена 26.08.2026, начисления на будущее невозможны. Фактические дни до оплаты: 12697 — 132, 14271/14273/14277 — 124, 15066 — 119, 15441 — 118, 17160 — 106, 17562 — 105.

ПРОСИМ: исключить 94 643,66 руб.')
